class SecureCookieSessionInterface:
    def open_session(self, app, request):
        val = request.cookies.get(app.session_cookie_name)
        if not val:
            return self.session_class()
        try:
            return serializer.loads(val)
        except (ValueError, KeyError):
            return self.session_class()
        except BadSignature:
            return self.session_class()

